package main

import "strconv"

type Value struct {
	Kind, Text, Builtin string
	Integer             int64
	Boolean             bool
	Items               []*Value
	Parameter           Token
	Body                *Expr
	Env                 ValueEnv
}
type ValueEnv map[string]*Value
type RuntimeError struct {
	Position
	Message string
}
type Evaluator struct{ Calls int }

func intValue(v int64) *Value     { return &Value{Kind: "integer", Integer: v} }
func boolValue(v bool) *Value     { return &Value{Kind: "boolean", Boolean: v} }
func stringValue(v string) *Value { return &Value{Kind: "string", Text: v} }
func copyValues(env ValueEnv) ValueEnv {
	out := ValueEnv{}
	for name, value := range env {
		out[name] = value
	}
	return out
}
func checked(v int64, pos Position) *Value {
	if v < -2147483648 || v > 2147483647 {
		panic(&RuntimeError{pos, "integer overflow"})
	}
	return intValue(v)
}
func compareValues(a, b *Value, pos Position) int {
	switch a.Kind {
	case "integer":
		if a.Integer < b.Integer {
			return -1
		}
		if a.Integer > b.Integer {
			return 1
		}
		return 0
	case "boolean":
		if a.Boolean == b.Boolean {
			return 0
		}
		if a.Boolean {
			return 1
		}
		return -1
	case "string":
		if a.Text < b.Text {
			return -1
		}
		if a.Text > b.Text {
			return 1
		}
		return 0
	case "function":
		panic(&RuntimeError{pos, "functional value compared"})
	case "pair", "list":
		for j := 0; j < len(a.Items) && j < len(b.Items); j++ {
			if c := compareValues(a.Items[j], b.Items[j], pos); c != 0 {
				return c
			}
		}
		if len(a.Items) < len(b.Items) {
			return -1
		}
		if len(a.Items) > len(b.Items) {
			return 1
		}
	}
	return 0
}
func matchPattern(p *Expr, v *Value, bindings ValueEnv) bool {
	switch p.Kind {
	case "wildcard":
		return true
	case "name":
		bindings[p.Value] = v
		return true
	case "integer":
		return p.Integer == v.Integer
	case "string":
		return p.Value == v.Text
	case "boolean":
		return (p.Value == "true") == v.Boolean
	case "pair":
		return matchPattern(p.Children[0], v.Items[0], bindings) && matchPattern(p.Children[1], v.Items[1], bindings)
	case "list":
		if len(p.Children) != len(v.Items) {
			return false
		}
		for j, child := range p.Children {
			if !matchPattern(child, v.Items[j], bindings) {
				return false
			}
		}
		return true
	case "cons":
		return len(v.Items) > 0 && matchPattern(p.Children[0], v.Items[0], bindings) && matchPattern(p.Children[1], &Value{Kind: "list", Items: v.Items[1:]}, bindings)
	}
	return false
}
func (v *Evaluator) apply(f, a *Value, pos Position) *Value {
	v.Calls++
	if f.Builtin != "" {
		switch f.Builtin {
		case "fst":
			return a.Items[0]
		case "snd":
			return a.Items[1]
		case "not":
			return boolValue(!a.Boolean)
		case "string_of_int":
			return stringValue(strconv.FormatInt(a.Integer, 10))
		case "failwith":
			panic(&RuntimeError{pos, "failure " + printValue(a)})
		}
	}
	inner := copyValues(f.Env)
	if f.Parameter.Spelling != "_" {
		inner[f.Parameter.Spelling] = a
	}
	return v.expression(f.Body, inner)
}
func (v *Evaluator) expression(e *Expr, env ValueEnv) *Value {
	c := e.Children
	switch e.Kind {
	case "integer":
		return intValue(e.Integer)
	case "boolean":
		return boolValue(e.Value == "true")
	case "string":
		return stringValue(e.Value)
	case "name":
		return env[e.Value]
	case "fun":
		return &Value{Kind: "function", Parameter: e.Token, Body: c[0], Env: env}
	case "apply":
		function := v.expression(c[0], env)
		argument := v.expression(c[1], env)
		return v.apply(function, argument, e.Position)
	case "negate":
		value := v.expression(c[0], env)
		return checked(-value.Integer, e.Token.Position)
	case "if":
		condition := v.expression(c[0], env)
		if condition.Boolean {
			return v.expression(c[1], env)
		}
		return v.expression(c[2], env)
	case "pair", "list":
		values := []*Value{}
		for _, child := range c {
			values = append(values, v.expression(child, env))
		}
		return &Value{Kind: e.Kind, Items: values}
	case "let":
		inner, _ := v.group(e.Group, env)
		return v.expression(c[0], inner)
	case "match":
		value := v.expression(c[0], env)
		for _, arm := range e.Arms {
			bindings := ValueEnv{}
			if matchPattern(arm.Pattern, value, bindings) {
				inner := copyValues(env)
				for name, matched := range bindings {
					inner[name] = matched
				}
				return v.expression(arm.Body, inner)
			}
		}
		panic(&RuntimeError{e.Position, "match failure"})
	case "binary":
		left := v.expression(c[0], env)
		op := e.Token.Spelling
		if op == "&&" && !left.Boolean {
			return boolValue(false)
		}
		if op == "||" && left.Boolean {
			return boolValue(true)
		}
		right := v.expression(c[1], env)
		pos := e.Token.Position
		switch op {
		case "&&", "||":
			return right
		case "+":
			return checked(left.Integer+right.Integer, pos)
		case "-":
			return checked(left.Integer-right.Integer, pos)
		case "*":
			return checked(left.Integer*right.Integer, pos)
		case "/", "mod":
			if right.Integer == 0 {
				panic(&RuntimeError{pos, "division by zero"})
			}
			quotient := left.Integer / right.Integer
			if op == "/" {
				return checked(quotient, pos)
			}
			return intValue(left.Integer - right.Integer*quotient)
		case "^":
			return stringValue(left.Text + right.Text)
		case "::":
			items := append([]*Value{left}, right.Items...)
			return &Value{Kind: "list", Items: items}
		default:
			comparison := compareValues(left, right, pos)
			answer := false
			switch op {
			case "=":
				answer = comparison == 0
			case "<>":
				answer = comparison != 0
			case "<":
				answer = comparison < 0
			case ">":
				answer = comparison > 0
			case "<=":
				answer = comparison <= 0
			case ">=":
				answer = comparison >= 0
			}
			return boolValue(answer)
		}
	}
	return nil
}
func (v *Evaluator) group(g *Group, env ValueEnv) (ValueEnv, []*Value) {
	inner := copyValues(env)
	values := make([]*Value, len(g.Bindings))
	if g.Rec == nil {
		for j, binding := range g.Bindings {
			values[j] = v.expression(binding.Expr, env)
		}
		for j, binding := range g.Bindings {
			inner[binding.Name.Spelling] = values[j]
		}
	} else {
		for j, binding := range g.Bindings {
			e := binding.Expr
			values[j] = &Value{Kind: "function", Parameter: e.Token, Body: e.Children[0], Env: inner}
			inner[binding.Name.Spelling] = values[j]
		}
	}
	return inner, values
}

package main

type TypeError struct {
	Kind, Name string
	Position
	Expected, Found *Type
	Failure         *UnificationFailure
	Candidates      []string
}
type Inferencer struct{ Locals []*Binding }

func (i *Inferencer) check(expected, found *Type, pos Position) {
	if failure := unify(expected, found, false); failure != nil {
		panic(&TypeError{Kind: "check", Position: pos, Expected: expected, Found: found, Failure: failure})
	}
}
func operatorTypes(op string) (*Type, *Type, *Type) {
	if wordIn("+ - * / mod", op) {
		return intType, intType, intType
	}
	if op == "^" {
		return stringType, stringType, stringType
	}
	if op == "&&" || op == "||" {
		return boolType, boolType, boolType
	}
	variable := fresh()
	if op == "::" {
		sequence := constructed("list", variable)
		return variable, sequence, sequence
	}
	return variable, variable, boolType
}
func (i *Inferencer) expression(e *Expr, env TypeEnv) *Type {
	var result *Type
	c := e.Children
	switch e.Kind {
	case "integer":
		result = intType
	case "string":
		result = stringType
	case "boolean":
		result = boolType
	case "name":
		scheme, ok := env[e.Value]
		if !ok {
			names := []string{}
			for name := range env {
				names = append(names, name)
			}
			panic(&TypeError{Kind: "unbound", Name: e.Value, Position: e.Position, Candidates: names})
		}
		result = instantiate(scheme)
	case "fun":
		argument := fresh()
		inner := copyTypes(env)
		if e.Token.Spelling != "_" {
			inner[e.Token.Spelling] = Scheme{Type: argument}
		}
		result = constructed("function", argument, i.expression(c[0], inner))
	case "apply":
		function := resolve(i.expression(c[0], env))
		var argument *Type
		if function.Kind == "var" {
			argument = fresh()
			result = fresh()
			function.Binding = constructed("function", argument, result)
		} else if function.Kind == "function" {
			argument, result = function.Children[0], function.Children[1]
		} else {
			panic(&TypeError{Kind: "not_function", Position: c[0].Position, Found: function})
		}
		found := i.expression(c[1], env)
		i.check(argument, found, c[1].Position)
	case "binary":
		first, second, r := operatorTypes(e.Token.Spelling)
		left := i.expression(c[0], env)
		i.check(first, left, c[0].Position)
		right := i.expression(c[1], env)
		i.check(second, right, c[1].Position)
		result = r
	case "negate":
		found := i.expression(c[0], env)
		i.check(intType, found, c[0].Position)
		result = intType
	case "if":
		condition := i.expression(c[0], env)
		i.check(boolType, condition, c[0].Position)
		result = i.expression(c[1], env)
		other := i.expression(c[2], env)
		i.check(result, other, c[2].Position)
	case "pair":
		first := i.expression(c[0], env)
		second := i.expression(c[1], env)
		result = constructed("pair", first, second)
	case "list":
		element := fresh()
		for _, child := range c {
			found := i.expression(child, env)
			i.check(element, found, child.Position)
		}
		result = constructed("list", element)
	case "match":
		matched := i.expression(c[0], env)
		result = fresh()
		for _, arm := range e.Arms {
			bindings := map[string]*Type{}
			patternType := i.pattern(arm.Pattern, bindings)
			i.check(matched, patternType, arm.Pattern.Position)
			inner := copyTypes(env)
			for name, t := range bindings {
				inner[name] = Scheme{Type: t}
			}
			found := i.expression(arm.Body, inner)
			i.check(result, found, arm.Body.Position)
		}
	case "let":
		inner := i.group(e.Group, env, true)
		result = i.expression(c[0], inner)
	}
	e.Inferred = result
	return result
}
func (i *Inferencer) pattern(p *Expr, bindings map[string]*Type) *Type {
	c := p.Children
	switch p.Kind {
	case "wildcard":
		return fresh()
	case "name":
		if _, ok := bindings[p.Value]; ok {
			panic(&TypeError{Kind: "duplicate_pattern", Name: p.Value, Position: p.Position})
		}
		t := fresh()
		bindings[p.Value] = t
		return t
	case "integer":
		return intType
	case "boolean":
		return boolType
	case "string":
		return stringType
	case "pair":
		first := i.pattern(c[0], bindings)
		second := i.pattern(c[1], bindings)
		return constructed("pair", first, second)
	}
	element := fresh()
	sequence := constructed("list", element)
	if p.Kind == "cons" {
		first := i.pattern(c[0], bindings)
		i.check(element, first, c[0].Position)
		second := i.pattern(c[1], bindings)
		i.check(sequence, second, c[1].Position)
	} else {
		for _, child := range c {
			found := i.pattern(child, bindings)
			i.check(element, found, child.Position)
		}
	}
	return sequence
}
func (i *Inferencer) group(g *Group, env TypeEnv, local bool) TypeEnv {
	seen := map[string]bool{}
	for _, binding := range g.Bindings {
		name := binding.Name.Spelling
		if seen[name] {
			panic(&TypeError{Kind: "duplicate_let", Name: name, Position: binding.Name.Position})
		}
		seen[name] = true
		if g.Rec != nil && binding.Expr.Kind != "fun" {
			panic(&TypeError{Kind: "recursive_function", Name: name, Position: binding.Name.Position})
		}
	}
	types := make([]*Type, len(g.Bindings))
	if g.Rec == nil {
		for j, binding := range g.Bindings {
			types[j] = i.expression(binding.Expr, env)
		}
	} else {
		recursive := copyTypes(env)
		for j, binding := range g.Bindings {
			types[j] = fresh()
			recursive[binding.Name.Spelling] = Scheme{Type: types[j]}
		}
		for j, binding := range g.Bindings {
			found := i.expression(binding.Expr, recursive)
			i.check(types[j], found, binding.Name.Position)
		}
	}
	result := copyTypes(env)
	for j, binding := range g.Bindings {
		binding.Scheme = generalize(types[j], env)
		result[binding.Name.Spelling] = binding.Scheme
	}
	if local {
		i.Locals = append(i.Locals, g.Bindings...)
	}
	return result
}

package main

import (
	"strconv"
	"strings"
)

type Position struct {
	File         string
	Line, Column int
}
type Token struct {
	Kind, Spelling, Value string
	Position
	Integer int64
}

func wordIn(words, value string) bool {
	for _, word := range strings.Fields(words) {
		if word == value {
			return true
		}
	}
	return false
}
func letter(c byte) bool   { return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' }
func digit(c byte) bool    { return c >= '0' && c <= '9' }
func (t Token) name() bool { return t.Kind == "identifier" && t.Spelling != "_" }
func lex(filename string, lines []string) []Token {
	source := strings.Join(lines, "\n")
	if len(lines) > 0 {
		source += "\n"
	}
	positions := make([]Position, len(source)+1)
	line, column := 1, 1
	for i := 0; i < len(source); i++ {
		positions[i] = Position{filename, line, column}
		if source[i] == '\n' {
			line++
			column = 1
		} else {
			column++
		}
	}
	positions[len(source)] = Position{filename, len(lines) + 1, 1}
	out := []Token{}
	for i := 0; i < len(source); {
		c := source[i]
		if c == ' ' || c == '\n' {
			i++
			continue
		}
		start := i
		token := Token{Position: positions[start]}
		if strings.HasPrefix(source[i:], "(*") {
			end := strings.Index(source[i+2:], "*)")
			if end < 0 {
				out = append(out, Token{Kind: "invalid", Value: "unterminated comment", Position: positions[start]})
				break
			}
			i += end + 4
			continue
		}
		if digit(c) {
			i++
			for i < len(source) && digit(source[i]) {
				i++
			}
			token.Spelling = source[start:i]
			token.Kind = "integer"
			digits := strings.TrimLeft(token.Spelling, "0")
			if len(digits) > 10 || len(digits) == 10 && digits > "2147483647" {
				token.Kind = "invalid"
				token.Value = "integer literal too large"
			} else {
				token.Integer, _ = strconv.ParseInt(token.Spelling, 10, 64)
			}
			out = append(out, token)
			continue
		}
		if letter(c) || c == '_' {
			i++
			for i < len(source) && (letter(source[i]) || digit(source[i]) || source[i] == '_' || source[i] == '\'') {
				i++
			}
			token.Spelling = source[start:i]
			token.Kind = "identifier"
			if wordIn("let rec and in fun if then else match with true false mod val", token.Spelling) {
				token.Kind = token.Spelling
			}
			out = append(out, token)
			continue
		}
		if c == '\'' && i+1 < len(source) && source[i+1] >= 'a' && source[i+1] <= 'z' {
			i += 2
			for i < len(source) && (letter(source[i]) || digit(source[i]) || source[i] == '_') {
				i++
			}
			token.Kind = "type_variable"
			token.Spelling = source[start:i]
			out = append(out, token)
			continue
		}
		if c == '"' {
			i++
			bad := false
			var value strings.Builder
			for i < len(source) && source[i] != '\n' && source[i] != '"' {
				if source[i] == '\\' && i+1 < len(source) && source[i+1] != '\n' {
					next := source[i+1]
					switch next {
					case 'n':
						value.WriteByte('\n')
					case 't':
						value.WriteByte('\t')
					case '\\', '"':
						value.WriteByte(next)
					default:
						bad = true
					}
					i += 2
				} else {
					value.WriteByte(source[i])
					i++
				}
			}
			token.Kind = "string"
			token.Value = value.String()
			if i == len(source) || source[i] == '\n' {
				token.Kind = "invalid"
				token.Value = "unterminated string"
			} else {
				i++
				if bad {
					token.Kind = "invalid"
					token.Value = "invalid escape sequence"
				}
			}
			token.Spelling = source[start:i]
			out = append(out, token)
			continue
		}
		found := ""
		for _, symbol := range strings.Fields(";; -> :: : || && <= >= <> ; = < > + - * / ^ ( ) [ ] , |") {
			if strings.HasPrefix(source[i:], symbol) && len(symbol) > len(found) {
				found = symbol
			}
		}
		if found != "" {
			i += len(found)
			token.Kind = found
			token.Spelling = found
		} else {
			i++
			token.Kind = "invalid"
			token.Spelling = string(c)
			token.Value = "illegal character '" + string(c) + "'"
		}
		out = append(out, token)
	}
	out = append(out, Token{Kind: "EOF", Position: positions[len(source)]})
	return out
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type TypePrinter struct {
	Names      map[*Type]string
	Quantified map[*Type]bool
	Local      bool
}

func (p *TypePrinter) print(t *Type) string {
	t = resolve(t)
	if t.Kind == "var" {
		if p.Names == nil {
			p.Names = map[*Type]string{}
		}
		if name, ok := p.Names[t]; ok {
			return name
		}
		index := len(p.Names)
		prefix := "'"
		if p.Local && !p.Quantified[t] {
			prefix = "'_"
		}
		name := prefix + string(rune('a'+index%26))
		if index >= 26 {
			name += strconv.Itoa(index / 26)
		}
		p.Names[t] = name
		return name
	}
	if wordIn("int bool string", t.Kind) {
		return t.Kind
	}
	first := resolve(t.Children[0])
	left := p.print(first)
	if t.Kind == "list" {
		if first.Kind == "pair" || first.Kind == "function" {
			left = "(" + left + ")"
		}
		return left + " list"
	}
	second := resolve(t.Children[1])
	right := p.print(second)
	if t.Kind == "pair" {
		if first.Kind == "pair" || first.Kind == "function" {
			left = "(" + left + ")"
		}
		if second.Kind == "pair" || second.Kind == "function" {
			right = "(" + right + ")"
		}
		return left + " * " + right
	}
	if first.Kind == "function" {
		left = "(" + left + ")"
	}
	return left + " -> " + right
}
func signatureType(e *Expr, variables map[string]*Type) *Type {
	if e.Kind == "type_variable" {
		if variables[e.Value] == nil {
			variables[e.Value] = fresh()
		}
		return variables[e.Value]
	}
	children := []*Type{}
	for _, child := range e.Children {
		children = append(children, signatureType(child, variables))
	}
	return constructed(e.Kind, children...)
}
func identicalTypes(a, b *Type) bool {
	a, b = resolve(a), resolve(b)
	if a.Kind == "var" || b.Kind == "var" {
		return a == b
	}
	if a.Kind != b.Kind {
		return false
	}
	for j, child := range a.Children {
		if !identicalTypes(child, b.Children[j]) {
			return false
		}
	}
	return true
}
func signatureMatches(inferred, declared *Type, assignments map[*Type]*Type) bool {
	inferred, declared = resolve(inferred), resolve(declared)
	if inferred.Kind == "var" {
		if previous, exists := assignments[inferred]; exists {
			return identicalTypes(previous, declared)
		}
		assignments[inferred] = declared
		return true
	}
	if declared.Kind == "var" || inferred.Kind != declared.Kind {
		return false
	}
	for j, child := range inferred.Children {
		if !signatureMatches(child, declared.Children[j], assignments) {
			return false
		}
	}
	return true
}
func checkSignatures(g *Group, signatures []*Item) {
	for j, binding := range g.Bindings {
		signature := signatures[j]
		if signature == nil {
			continue
		}
		declared := signatureType(signature.Declared, map[string]*Type{})
		inferred := binding.Scheme.Type
		if !signatureMatches(inferred, declared, map[*Type]*Type{}) {
			panic(&TypeError{Kind: "signature", Name: binding.Name.Spelling, Position: binding.Name.Position, Expected: inferred, Found: declared})
		}
		binding.Scheme = Scheme{declared, freeVariables(declared)}
	}
}
func editDistance(a, b string) int {
	previous := make([]int, len(b)+1)
	for j := range previous {
		previous[j] = j
	}
	for i := 0; i < len(a); i++ {
		current := make([]int, len(b)+1)
		current[0] = i + 1
		for j := 0; j < len(b); j++ {
			substitution := 0
			if a[i] != b[j] {
				substitution = 1
			}
			current[j+1] = min(current[j]+1, previous[j+1]+1, previous[j]+substitution)
		}
		previous = current
	}
	return previous[len(b)]
}
func typeErrorMessage(err *TypeError) string {
	printer := &TypePrinter{}
	switch err.Kind {
	case "unbound":
		message := "unbound variable '" + err.Name + "'"
		best, bestDistance := "", 3
		for _, candidate := range err.Candidates {
			distance := editDistance(err.Name, candidate)
			if distance <= 2 && distance < len(err.Name) && (distance < bestDistance || distance == bestDistance && (best == "" || candidate < best)) {
				best = candidate
				bestDistance = distance
			}
		}
		if best != "" {
			message += " (did you mean '" + best + "'?)"
		}
		return message
	case "not_function":
		return "expected a function but found " + printer.print(err.Found)
	case "duplicate_pattern":
		return "variable '" + err.Name + "' is bound twice in this pattern"
	case "duplicate_let":
		return "variable '" + err.Name + "' is bound twice in this let"
	case "recursive_function":
		return "'" + err.Name + "' in let rec must be a function"
	case "signature":
		return "'" + err.Name + "' has type " + printer.print(err.Expected) + " but its signature is " + printer.print(err.Found)
	case "check":
		message := "expected " + printer.print(err.Expected) + " but found " + printer.print(err.Found)
		failure := err.Failure
		if failure.Infinite {
			variable, value := failure.Expected, failure.Found
			if variable.Kind != "var" {
				variable, value = value, variable
			}
			message += " (infinite type " + printer.print(variable) + " = " + printer.print(value) + ")"
		} else if failure.Nested {
			message += " (" + printer.print(failure.Expected) + " vs " + printer.print(failure.Found) + ")"
		}
		return message
	}
	return ""
}
func builtins() (TypeEnv, ValueEnv) {
	types := TypeEnv{}
	values := ValueEnv{}
	for _, name := range []string{"fst", "snd"} {
		a, b := fresh(), fresh()
		result := a
		if name == "snd" {
			result = b
		}
		types[name] = Scheme{constructed("function", constructed("pair", a, b), result), map[*Type]bool{a: true, b: true}}
	}
	types["not"] = Scheme{Type: constructed("function", boolType, boolType)}
	types["string_of_int"] = Scheme{Type: constructed("function", intType, stringType)}
	result := fresh()
	types["failwith"] = Scheme{constructed("function", stringType, result), map[*Type]bool{result: true}}
	for name := range types {
		values[name] = &Value{Kind: "function", Builtin: name}
	}
	return types, values
}
func quoteString(value string) string {
	var b strings.Builder
	b.WriteByte('"')
	for j := 0; j < len(value); j++ {
		switch value[j] {
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		case '\n':
			b.WriteString(`\n`)
		case '\t':
			b.WriteString(`\t`)
		default:
			b.WriteByte(value[j])
		}
	}
	b.WriteByte('"')
	return b.String()
}
func printValue(v *Value) string {
	switch v.Kind {
	case "integer":
		return strconv.FormatInt(v.Integer, 10)
	case "boolean":
		if v.Boolean {
			return "true"
		}
		return "false"
	case "string":
		return quoteString(v.Text)
	case "pair":
		return "(" + printValue(v.Items[0]) + ", " + printValue(v.Items[1]) + ")"
	case "list":
		parts := []string{}
		for _, item := range v.Items {
			parts = append(parts, printValue(item))
		}
		return "[" + strings.Join(parts, "; ") + "]"
	}
	return "<fun>"
}
func declaredType(e *Expr) string {
	if e.Kind == "type_variable" {
		return e.Value
	}
	if wordIn("int bool string", e.Kind) {
		return e.Kind
	}
	first := e.Children[0]
	left := declaredType(first)
	if e.Kind == "list" {
		if first.Kind == "pair" || first.Kind == "function" {
			left = "(" + left + ")"
		}
		return left + " list"
	}
	second := e.Children[1]
	right := declaredType(second)
	if e.Kind == "pair" {
		if first.Kind == "pair" || first.Kind == "function" {
			left = "(" + left + ")"
		}
		if second.Kind == "pair" || second.Kind == "function" {
			right = "(" + right + ")"
		}
		return left + " * " + right
	}
	if first.Kind == "function" {
		left = "(" + left + ")"
	}
	return left + " -> " + right
}
func parameters(e *Expr) ([]string, *Expr) {
	names := []string{}
	for e.Kind == "fun" {
		names = append(names, e.Token.Spelling)
		e = e.Children[0]
	}
	return names, e
}
func formatGroup(g *Group) string {
	prefix := "let "
	if g.Rec != nil {
		prefix = "let rec "
	}
	parts := []string{}
	for _, binding := range g.Bindings {
		params, body := parameters(binding.Expr)
		words := append([]string{binding.Name.Spelling}, params...)
		words = append(words, "=", formatExpression(body, 0))
		parts = append(parts, strings.Join(words, " "))
	}
	return prefix + strings.Join(parts, " and ")
}
func endsWithMatch(e *Expr) bool {
	if e.Kind == "match" {
		return true
	}
	if e.Kind == "let" || e.Kind == "fun" {
		return endsWithMatch(e.Children[0])
	}
	if e.Kind == "if" {
		return endsWithMatch(e.Children[2])
	}
	return false
}
func formatPattern(p *Expr) string {
	switch p.Kind {
	case "wildcard", "name":
		return p.Value
	case "integer":
		return strconv.FormatInt(p.Integer, 10)
	case "string":
		return quoteString(p.Value)
	case "boolean":
		return p.Value
	case "list":
		parts := []string{}
		for _, child := range p.Children {
			parts = append(parts, formatPattern(child))
		}
		return "[" + strings.Join(parts, "; ") + "]"
	case "pair":
		return "(" + formatPattern(p.Children[0]) + ", " + formatPattern(p.Children[1]) + ")"
	case "cons":
		left := formatPattern(p.Children[0])
		if p.Children[0].Kind == "cons" {
			left = "(" + left + ")"
		}
		return left + " :: " + formatPattern(p.Children[1])
	}
	return ""
}
func formatExpression(e *Expr, minimum int) string {
	strength := 9
	text := ""
	c := e.Children
	switch e.Kind {
	case "integer":
		text = strconv.FormatInt(e.Integer, 10)
	case "boolean", "name":
		text = e.Value
	case "string":
		text = quoteString(e.Value)
	case "fun":
		strength = 0
		params, body := parameters(e)
		text = "fun " + strings.Join(params, " ") + " -> " + formatExpression(body, 0)
	case "apply":
		strength = 8
		text = formatExpression(c[0], 8) + " " + formatExpression(c[1], 9)
	case "binary":
		var right bool
		strength, right = operator(e.Token.Spelling)
		leftMin, rightMin := strength, strength+1
		if right {
			leftMin, rightMin = strength+1, strength
		}
		text = formatExpression(c[0], leftMin) + " " + e.Token.Spelling + " " + formatExpression(c[1], rightMin)
	case "negate":
		strength = 7
		text = "-" + formatExpression(c[0], 7)
	case "if":
		strength = 0
		text = "if " + formatExpression(c[0], 0) + " then " + formatExpression(c[1], 0) + " else " + formatExpression(c[2], 0)
	case "pair":
		text = "(" + formatExpression(c[0], 0) + ", " + formatExpression(c[1], 0) + ")"
	case "list":
		parts := []string{}
		for _, child := range c {
			parts = append(parts, formatExpression(child, 0))
		}
		text = "[" + strings.Join(parts, "; ") + "]"
	case "let":
		strength = 0
		text = formatGroup(e.Group) + " in " + formatExpression(c[0], 0)
	case "match":
		strength = 0
		parts := []string{}
		for j, arm := range e.Arms {
			body := formatExpression(arm.Body, 0)
			if j+1 < len(e.Arms) && endsWithMatch(arm.Body) {
				body = "(" + body + ")"
			}
			parts = append(parts, formatPattern(arm.Pattern)+" -> "+body)
		}
		text = "match " + formatExpression(c[0], 0) + " with " + strings.Join(parts, " | ")
	}
	if strength < minimum {
		text = "(" + text + ")"
	}
	return text
}
func formatItem(item *Item) string {
	switch item.Kind {
	case "signature":
		return "val " + item.Name.Spelling + " : " + declaredType(item.Declared) + ";;"
	case "declaration":
		return formatGroup(item.Group) + ";;"
	}
	return formatExpression(item.Expr, 0) + ";;"
}

type Cover struct {
	Tag      string
	Children []*Cover
}

func coveragePattern(p *Expr) *Cover {
	switch p.Kind {
	case "name", "wildcard":
		return nil
	case "integer":
		return &Cover{Tag: "i:" + strconv.FormatInt(p.Integer, 10)}
	case "string":
		return &Cover{Tag: "s:" + quoteString(p.Value)}
	case "boolean":
		return &Cover{Tag: "b:" + p.Value}
	case "list":
		out := &Cover{Tag: "nil"}
		for j := len(p.Children) - 1; j >= 0; j-- {
			out = &Cover{Tag: "cons", Children: []*Cover{coveragePattern(p.Children[j]), out}}
		}
		return out
	default:
		children := []*Cover{}
		for _, child := range p.Children {
			children = append(children, coveragePattern(child))
		}
		return &Cover{Tag: p.Kind, Children: children}
	}
}
func constructors(t *Type) []string {
	switch resolve(t).Kind {
	case "bool":
		return []string{"b:false", "b:true"}
	case "list":
		return []string{"nil", "cons"}
	case "pair":
		return []string{"pair"}
	}
	return nil
}
func constructorTypes(tag string, t *Type) []*Type {
	t = resolve(t)
	if tag == "pair" {
		return t.Children
	}
	if tag == "cons" {
		return []*Type{t.Children[0], t}
	}
	return nil
}
func specialize(matrix [][]*Cover, tag string, arity int) [][]*Cover {
	out := [][]*Cover{}
	for _, row := range matrix {
		head := row[0]
		if head == nil {
			out = append(out, append(make([]*Cover, arity), row[1:]...))
		} else if head.Tag == tag {
			next := append([]*Cover{}, head.Children...)
			out = append(out, append(next, row[1:]...))
		}
	}
	return out
}
func coverCode(p *Cover) string {
	if p == nil {
		return "_"
	}
	parts := ""
	for _, child := range p.Children {
		parts += coverCode(child)
	}
	return strconv.Itoa(len(p.Tag)) + ":" + p.Tag + "(" + parts + ")"
}
func coverageTypeCode(t *Type) string {
	t = resolve(t)
	if t.Kind == "var" || t.Kind == "function" {
		return "opaque"
	}
	out := t.Kind + "("
	for _, child := range t.Children {
		out += coverageTypeCode(child)
	}
	return out + ")"
}

type Coverage struct{ Memo map[string]bool }

func (c *Coverage) useful(matrix [][]*Cover, query []*Cover, types []*Type) bool {
	var key strings.Builder
	for _, row := range matrix {
		key.WriteByte('[')
		for _, p := range row {
			key.WriteString(coverCode(p))
		}
		key.WriteByte(']')
	}
	key.WriteByte('?')
	for _, p := range query {
		key.WriteString(coverCode(p))
	}
	key.WriteByte(':')
	for _, t := range types {
		key.WriteString(coverageTypeCode(t))
	}
	code := key.String()
	if value, exists := c.Memo[code]; exists {
		return value
	}
	value := c.compute(matrix, query, types)
	c.Memo[code] = value
	return value
}
func (c *Coverage) compute(matrix [][]*Cover, query []*Cover, types []*Type) bool {
	if len(query) == 0 {
		return len(matrix) == 0
	}
	if len(matrix) == 0 {
		return true
	}
	head := query[0]
	if head != nil {
		argumentTypes := constructorTypes(head.Tag, types[0])
		nextQuery := append(append([]*Cover{}, head.Children...), query[1:]...)
		nextTypes := append(append([]*Type{}, argumentTypes...), types[1:]...)
		return c.useful(specialize(matrix, head.Tag, len(head.Children)), nextQuery, nextTypes)
	}
	possible := constructors(types[0])
	present := map[string]bool{}
	for _, row := range matrix {
		if row[0] != nil {
			present[row[0].Tag] = true
		}
	}
	complete := len(possible) > 0
	for _, tag := range possible {
		if !present[tag] {
			complete = false
		}
	}
	if complete {
		for _, tag := range possible {
			arguments := constructorTypes(tag, types[0])
			next := append(make([]*Cover, len(arguments)), query[1:]...)
			nextTypes := append(append([]*Type{}, arguments...), types[1:]...)
			if c.useful(specialize(matrix, tag, len(arguments)), next, nextTypes) {
				return true
			}
		}
		return false
	}
	defaults := [][]*Cover{}
	for _, row := range matrix {
		if row[0] == nil {
			defaults = append(defaults, row[1:])
		}
	}
	return c.useful(defaults, query[1:], types[1:])
}

type Symbol struct {
	Name string
	Position
	Top, Used bool
}
type Warning struct {
	Position
	Order   int
	Message string
}
type GroupSymbols struct {
	Group   *Group
	Targets map[*Symbol]bool
}
type StaticChecks struct {
	Symbols    []*Symbol
	References map[*Expr]*Symbol
	Groups     []GroupSymbols
	Warnings   []Warning
}

func copySymbols(env map[string]*Symbol) map[string]*Symbol {
	out := map[string]*Symbol{}
	for name, symbol := range env {
		out[name] = symbol
	}
	return out
}
func (s *StaticChecks) symbol(name string, pos Position, top bool) *Symbol {
	symbol := &Symbol{Name: name, Position: pos, Top: top}
	s.Symbols = append(s.Symbols, symbol)
	return symbol
}
func (s *StaticChecks) pattern(p *Expr, env map[string]*Symbol) {
	if p.Kind == "name" {
		env[p.Value] = s.symbol(p.Value, p.Position, false)
	}
	for _, child := range p.Children {
		s.pattern(child, env)
	}
}
func (s *StaticChecks) group(g *Group, env map[string]*Symbol, top bool) map[string]*Symbol {
	inner := copySymbols(env)
	targets := map[*Symbol]bool{}
	for _, binding := range g.Bindings {
		symbol := s.symbol(binding.Name.Spelling, binding.Name.Position, top)
		inner[symbol.Name] = symbol
		targets[symbol] = true
	}
	s.Groups = append(s.Groups, GroupSymbols{g, targets})
	right := env
	if g.Rec != nil {
		right = inner
	}
	for _, binding := range g.Bindings {
		s.expression(binding.Expr, right)
	}
	return inner
}
func (s *StaticChecks) expression(e *Expr, env map[string]*Symbol) {
	switch e.Kind {
	case "name":
		symbol := env[e.Value]
		s.References[e] = symbol
		if symbol != nil {
			symbol.Used = true
		}
		return
	case "fun":
		inner := copySymbols(env)
		if e.Token.Spelling != "_" {
			inner[e.Token.Spelling] = s.symbol(e.Token.Spelling, e.Token.Position, false)
		}
		s.expression(e.Children[0], inner)
		return
	case "let":
		inner := s.group(e.Group, env, false)
		s.expression(e.Children[0], inner)
		return
	case "match":
		s.expression(e.Children[0], env)
		coverage := Coverage{map[string]bool{}}
		matrix := [][]*Cover{}
		types := []*Type{e.Children[0].Inferred}
		for j, arm := range e.Arms {
			query := []*Cover{coveragePattern(arm.Pattern)}
			if j > 0 && !coverage.useful(matrix, query, types) {
				s.Warnings = append(s.Warnings, Warning{arm.Pattern.Position, 2, "this match case is unused"})
			}
			matrix = append(matrix, query)
			inner := copySymbols(env)
			s.pattern(arm.Pattern, inner)
			s.expression(arm.Body, inner)
		}
		if coverage.useful(matrix, []*Cover{nil}, types) {
			s.Warnings = append(s.Warnings, Warning{e.Position, 1, "this match is not exhaustive"})
		}
		return
	}
	for _, child := range e.Children {
		s.expression(child, env)
	}
}
func walkExpr(e *Expr, visit func(*Expr)) {
	visit(e)
	if e.Group != nil {
		for _, binding := range e.Group.Bindings {
			walkExpr(binding.Expr, visit)
		}
	}
	for _, child := range e.Children {
		walkExpr(child, visit)
	}
	for _, arm := range e.Arms {
		walkExpr(arm.Body, visit)
	}
}
func (s *StaticChecks) classification(e *Expr, targets map[*Symbol]bool) string {
	_, body := parameters(e)
	references, allTail := 0, true
	var visit func(*Expr, bool)
	visit = func(n *Expr, tail bool) {
		c := n.Children
		switch n.Kind {
		case "name":
			if targets[s.References[n]] {
				references++
				allTail = false
			}
			return
		case "apply":
			arguments := []*Expr{}
			head := n
			for head.Kind == "apply" {
				arguments = append(arguments, head.Children[1])
				head = head.Children[0]
			}
			if head.Kind == "name" && targets[s.References[head]] {
				references++
				if !tail {
					allTail = false
				}
			} else {
				visit(head, false)
			}
			for j := len(arguments) - 1; j >= 0; j-- {
				visit(arguments[j], false)
			}
			return
		case "if":
			visit(c[0], false)
			visit(c[1], tail)
			visit(c[2], tail)
			return
		case "match":
			visit(c[0], false)
			for _, arm := range n.Arms {
				visit(arm.Body, tail)
			}
			return
		case "let":
			for _, binding := range n.Group.Bindings {
				visit(binding.Expr, false)
			}
			visit(c[0], tail)
			return
		case "binary":
			if n.Token.Spelling == "&&" || n.Token.Spelling == "||" {
				visit(c[0], false)
				visit(c[1], tail)
				return
			}
		}
		for _, child := range c {
			visit(child, false)
		}
	}
	visit(body, true)
	if references == 0 {
		return ""
	}
	if allTail {
		return "tail recursive"
	}
	return "recursive"
}
func staticWarnings(item *Item, env TypeEnv) []Warning {
	s := &StaticChecks{References: map[*Expr]*Symbol{}}
	names := map[string]*Symbol{}
	for name := range env {
		names[name] = nil
	}
	if item.Kind == "declaration" {
		s.group(item.Group, names, true)
	} else {
		s.expression(item.Expr, names)
	}
	for _, g := range s.Groups {
		if g.Group.Rec == nil {
			continue
		}
		used := false
		for _, binding := range g.Group.Bindings {
			walkExpr(binding.Expr, func(e *Expr) {
				if g.Targets[s.References[e]] {
					used = true
				}
			})
			binding.Classification = s.classification(binding.Expr, g.Targets)
		}
		if !used {
			s.Warnings = append(s.Warnings, Warning{*g.Group.Rec, 3, "unused rec flag"})
		}
	}
	for _, symbol := range s.Symbols {
		if !symbol.Top && !symbol.Used && !strings.HasPrefix(symbol.Name, "_") {
			s.Warnings = append(s.Warnings, Warning{symbol.Position, 4, "unused variable '" + symbol.Name + "'"})
		}
	}
	sort.SliceStable(s.Warnings, func(i, j int) bool {
		a, b := s.Warnings[i], s.Warnings[j]
		if a.Line != b.Line {
			return a.Line < b.Line
		}
		if a.Column != b.Column {
			return a.Column < b.Column
		}
		return a.Order < b.Order
	})
	return s.Warnings
}
func inferItem(item *Item, env TypeEnv, signatures []*Item) (inference *Inferencer, result *Type, failure *TypeError) {
	inference = &Inferencer{}
	defer func() {
		if value := recover(); value != nil {
			if err, ok := value.(*TypeError); ok {
				failure = err
			} else {
				panic(value)
			}
		}
	}()
	if item.Kind == "declaration" {
		inference.group(item.Group, env, false)
		checkSignatures(item.Group, signatures)
	} else {
		result = inference.expression(item.Expr, env)
	}
	return
}
func evaluateItem(item *Item, env ValueEnv, evaluator *Evaluator) (updated ValueEnv, values []*Value, failure *RuntimeError) {
	defer func() {
		if value := recover(); value != nil {
			if err, ok := value.(*RuntimeError); ok {
				failure = err
			} else {
				panic(value)
			}
		}
	}()
	if item.Kind == "declaration" {
		updated, values = evaluator.group(item.Group, env)
	} else {
		updated = env
		values = []*Value{evaluator.expression(item.Expr, env)}
	}
	return
}
func suffixClassification(binding *Binding) string {
	if binding.Classification == "" {
		return ""
	}
	return " (" + binding.Classification + ")"
}

type Counts struct{ Items, Bindings, Syntax, Type, Runtime, Warnings, Calls int }
type Reports struct {
	Sources map[string][]string
	Current string
	Stats   map[string]*Counts
	Lines   []string
}

func (r *Reports) report(kind string, pos Position, message string) {
	c := r.Stats[r.Current]
	switch kind {
	case "syntax error":
		c.Syntax++
	case "type error":
		c.Type++
	case "runtime error":
		c.Runtime++
	case "warning":
		c.Warnings++
	}
	r.Lines = append(r.Lines, fmt.Sprintf("%s:%d:%d: %s: %s", pos.File, pos.Line, pos.Column, kind, message))
	lines := r.Sources[pos.File]
	if pos.Line <= len(lines) {
		r.Lines = append(r.Lines, "    "+lines[pos.Line-1], strings.Repeat(" ", pos.Column+3)+"^")
	}
}
func syntaxMessage(t Token) string {
	if t.Kind == "invalid" {
		return t.Value
	}
	if t.Kind == "EOF" {
		return "unexpected end of file"
	}
	return "unexpected '" + t.Spelling + "'"
}
func readLines(path string) []string {
	f, err := os.Open(path)
	if err != nil {
		panic(err)
	}
	defer f.Close()
	lines := []string{}
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err = scanner.Err(); err != nil {
		panic(err)
	}
	return lines
}
func writeLines(path string, lines []string) {
	value := strings.Join(lines, "\n") + "\n"
	if err := os.WriteFile("output/"+path, []byte(value), 0644); err != nil {
		panic(err)
	}
}
func main() {
	filenames := []string{"prelude.ml", "program.ml"}
	reports := &Reports{Sources: map[string][]string{}, Stats: map[string]*Counts{}}
	for _, filename := range filenames {
		reports.Sources[filename] = readLines("input/" + filename)
		reports.Stats[filename] = &Counts{}
	}
	typeEnv, valueEnv := builtins()
	types, values, formatted := []string{}, []string{}, []string{}
	for _, filename := range filenames {
		reports.Current = filename
		stats := reports.Stats[filename]
		pending := map[string]*Item{}
		types = append(types, "== "+filename+" ==")
		values = append(values, "== "+filename+" ==")
		formatted = append(formatted, "(* "+filename+" *)")
		parser := &Parser{Tokens: lex(filename, reports.Sources[filename])}
		evaluator := &Evaluator{}
		for parser.peek().Kind != "EOF" {
			stats.Items++
			item, syntax := parser.readItem()
			if syntax != nil {
				reports.report("syntax error", syntax.Token.Position, syntaxMessage(syntax.Token))
				parser.recoverItem()
				continue
			}
			formatted = append(formatted, formatItem(item))
			if item.Kind == "signature" {
				name := item.Name.Spelling
				if old := pending[name]; old != nil {
					reports.report("warning", old.Name.Position, "signature for '"+name+"' is never used")
				}
				pending[name] = item
				continue
			}
			signatures := []*Item{}
			if item.Kind == "declaration" {
				for _, binding := range item.Group.Bindings {
					name := binding.Name.Spelling
					signatures = append(signatures, pending[name])
					delete(pending, name)
				}
			}
			inference, inferred, typeFailure := inferItem(item, typeEnv, signatures)
			if typeFailure != nil {
				reports.report("type error", typeFailure.Position, typeErrorMessage(typeFailure))
				continue
			}
			warnings := staticWarnings(item, typeEnv)
			if item.Kind == "declaration" {
				for _, binding := range item.Group.Bindings {
					printer := &TypePrinter{}
					types = append(types, binding.Name.Spelling+" : "+printer.print(binding.Scheme.Type)+suffixClassification(binding))
				}
			} else {
				printer := &TypePrinter{}
				types = append(types, "- : "+printer.print(inferred))
			}
			sort.SliceStable(inference.Locals, func(i, j int) bool {
				a, b := inference.Locals[i].Name, inference.Locals[j].Name
				if a.Line != b.Line {
					return a.Line < b.Line
				}
				return a.Column < b.Column
			})
			for _, binding := range inference.Locals {
				printer := &TypePrinter{Quantified: binding.Scheme.Quantified, Local: true}
				types = append(types, fmt.Sprintf("  %s (%d:%d) : %s%s", binding.Name.Spelling, binding.Name.Line, binding.Name.Column, printer.print(binding.Scheme.Type), suffixClassification(binding)))
			}
			for _, warning := range warnings {
				reports.report("warning", warning.Position, warning.Message)
			}
			updated, evaluated, runtimeFailure := evaluateItem(item, valueEnv, evaluator)
			if runtimeFailure != nil {
				reports.report("runtime error", runtimeFailure.Position, runtimeFailure.Message)
				continue
			}
			if item.Kind == "declaration" {
				typeEnv = copyTypes(typeEnv)
				for j, binding := range item.Group.Bindings {
					name := binding.Name.Spelling
					typeEnv[name] = binding.Scheme
					values = append(values, name+" = "+printValue(evaluated[j]))
					stats.Bindings++
				}
				valueEnv = updated
			} else {
				values = append(values, "- = "+printValue(evaluated[0]))
			}
		}
		remaining := []*Item{}
		for _, signature := range pending {
			remaining = append(remaining, signature)
		}
		sort.Slice(remaining, func(i, j int) bool {
			a, b := remaining[i].Name, remaining[j].Name
			if a.Line != b.Line {
				return a.Line < b.Line
			}
			return a.Column < b.Column
		})
		for _, signature := range remaining {
			reports.report("warning", signature.Name.Position, "signature for '"+signature.Name.Spelling+"' is never used")
		}
		stats.Calls = evaluator.Calls
	}
	reports.Lines = append(reports.Lines, "== summary ==")
	for _, filename := range filenames {
		c := reports.Stats[filename]
		reports.Lines = append(reports.Lines, fmt.Sprintf("%s: items=%d bindings=%d syntax=%d type=%d runtime=%d warnings=%d calls=%d", filename, c.Items, c.Bindings, c.Syntax, c.Type, c.Runtime, c.Warnings, c.Calls))
	}
	if err := os.MkdirAll("output", 0755); err != nil {
		panic(err)
	}
	writeLines("types.txt", types)
	writeLines("values.txt", values)
	writeLines("errors.txt", reports.Lines)
	writeLines("formatted.ml", formatted)
}

package main

type Expr struct {
	Kind, Value string
	Position
	Integer  int64
	Children []*Expr
	Token    Token
	Group    *Group
	Arms     []Arm
	Inferred *Type
}
type Arm struct{ Pattern, Body *Expr }
type Binding struct {
	Name           Token
	Expr           *Expr
	Scheme         Scheme
	Classification string
}
type Group struct {
	Bindings []*Binding
	Rec      *Position
}
type Item struct {
	Kind     string
	Name     Token
	Declared *Expr
	Group    *Group
	Expr     *Expr
}
type SyntaxError struct{ Token Token }
type Parser struct {
	Tokens []Token
	Index  int
}

func (p *Parser) peek() Token { return p.Tokens[p.Index] }
func (p *Parser) accept(kind string) (Token, bool) {
	t := p.peek()
	if t.Kind != kind {
		return Token{}, false
	}
	p.Index++
	return t, true
}
func (p *Parser) expect(kind string) Token {
	if t, ok := p.accept(kind); ok {
		return t
	}
	panic(&SyntaxError{p.peek()})
}
func (p *Parser) name() Token {
	if !p.peek().name() {
		panic(&SyntaxError{p.peek()})
	}
	return p.expect("identifier")
}
func (p *Parser) recoverItem() {
	for p.peek().Kind != ";;" && p.peek().Kind != "EOF" {
		p.Index++
	}
	p.accept(";;")
}
func (p *Parser) item() *Item {
	if _, ok := p.accept("val"); ok {
		name := p.name()
		p.expect(":")
		declared := p.typeExpression()
		p.expect(";;")
		return &Item{Kind: "signature", Name: name, Declared: declared}
	}
	var item *Item
	if opening, ok := p.accept("let"); ok {
		g := p.group()
		if _, yes := p.accept("in"); yes {
			item = &Item{Kind: "expression", Expr: &Expr{Kind: "let", Position: opening.Position, Group: g, Children: []*Expr{p.expression()}}}
		} else {
			item = &Item{Kind: "declaration", Group: g}
		}
	} else {
		item = &Item{Kind: "expression", Expr: p.expression()}
	}
	p.expect(";;")
	return item
}
func (p *Parser) readItem() (item *Item, failure *SyntaxError) {
	defer func() {
		if value := recover(); value != nil {
			if err, ok := value.(*SyntaxError); ok {
				failure = err
			} else {
				panic(value)
			}
		}
	}()
	item = p.item()
	return
}
func (p *Parser) group() *Group {
	g := &Group{}
	if rec, ok := p.accept("rec"); ok {
		position := rec.Position
		g.Rec = &position
	}
	g.Bindings = append(g.Bindings, p.binding())
	for {
		if _, ok := p.accept("and"); !ok {
			break
		}
		g.Bindings = append(g.Bindings, p.binding())
	}
	return g
}
func (p *Parser) binding() *Binding {
	name := p.name()
	parameters := []Token{}
	for p.peek().Kind == "identifier" {
		parameters = append(parameters, p.expect("identifier"))
	}
	p.expect("=")
	e := p.expression()
	for i := len(parameters) - 1; i >= 0; i-- {
		e = &Expr{Kind: "fun", Position: parameters[i].Position, Token: parameters[i], Children: []*Expr{e}}
	}
	return &Binding{Name: name, Expr: e}
}
func operator(op string) (int, bool) {
	switch op {
	case "||":
		return 1, true
	case "&&":
		return 2, true
	case "=", "<>", "<", ">", "<=", ">=":
		return 3, false
	case "::", "^":
		return 4, true
	case "+", "-":
		return 5, false
	case "*", "/", "mod":
		return 6, false
	}
	return 0, false
}
func (p *Parser) expression() *Expr {
	if opening, ok := p.accept("let"); ok {
		g := p.group()
		p.expect("in")
		return &Expr{Kind: "let", Position: opening.Position, Group: g, Children: []*Expr{p.expression()}}
	}
	if opening, ok := p.accept("fun"); ok {
		parameters := []Token{p.expect("identifier")}
		for p.peek().Kind == "identifier" {
			parameters = append(parameters, p.expect("identifier"))
		}
		p.expect("->")
		e := p.expression()
		for i := len(parameters) - 1; i >= 0; i-- {
			e = &Expr{Kind: "fun", Position: parameters[i].Position, Token: parameters[i], Children: []*Expr{e}}
		}
		e.Position = opening.Position
		return e
	}
	if opening, ok := p.accept("if"); ok {
		condition := p.expression()
		p.expect("then")
		first := p.expression()
		p.expect("else")
		second := p.expression()
		return &Expr{Kind: "if", Position: opening.Position, Children: []*Expr{condition, first, second}}
	}
	if opening, ok := p.accept("match"); ok {
		e := p.expression()
		p.expect("with")
		p.accept("|")
		arms := []Arm{p.arm()}
		for {
			if _, yes := p.accept("|"); !yes {
				break
			}
			arms = append(arms, p.arm())
		}
		return &Expr{Kind: "match", Position: opening.Position, Children: []*Expr{e}, Arms: arms}
	}
	return p.binary(1)
}
func (p *Parser) arm() Arm {
	pattern := p.pattern()
	p.expect("->")
	return Arm{pattern, p.expression()}
}
func (p *Parser) binary(minimum int) *Expr {
	left := p.unary()
	for {
		precedence, rightAssociative := operator(p.peek().Kind)
		if precedence == 0 || precedence < minimum {
			break
		}
		op := p.peek()
		p.Index++
		next := precedence + 1
		if rightAssociative {
			next = precedence
		}
		right := p.binary(next)
		left = &Expr{Kind: "binary", Position: left.Position, Token: op, Children: []*Expr{left, right}}
	}
	return left
}
func startsAtom(t Token) bool { return wordIn("integer string true false ( [", t.Kind) || t.name() }
func (p *Parser) unary() *Expr {
	if op, ok := p.accept("-"); ok {
		return &Expr{Kind: "negate", Position: op.Position, Token: op, Children: []*Expr{p.unary()}}
	}
	e := p.atom()
	for startsAtom(p.peek()) {
		e = &Expr{Kind: "apply", Position: e.Position, Children: []*Expr{e, p.atom()}}
	}
	return e
}
func (p *Parser) atom() *Expr {
	t := p.peek()
	if t.Kind == "integer" || t.Kind == "string" {
		p.Index++
		return &Expr{Kind: t.Kind, Position: t.Position, Value: t.Value, Integer: t.Integer}
	}
	if t.Kind == "true" || t.Kind == "false" {
		p.Index++
		return &Expr{Kind: "boolean", Position: t.Position, Value: t.Kind}
	}
	if t.name() {
		p.Index++
		return &Expr{Kind: "name", Position: t.Position, Value: t.Spelling}
	}
	if _, ok := p.accept("("); ok {
		first := p.expression()
		if _, yes := p.accept(","); yes {
			second := p.expression()
			p.expect(")")
			return &Expr{Kind: "pair", Position: t.Position, Children: []*Expr{first, second}}
		}
		p.expect(")")
		return first
	}
	if _, ok := p.accept("["); ok {
		elements := []*Expr{}
		if _, yes := p.accept("]"); !yes {
			elements = append(elements, p.expression())
			for {
				if _, yes := p.accept(";"); !yes {
					break
				}
				elements = append(elements, p.expression())
			}
			p.expect("]")
		}
		return &Expr{Kind: "list", Position: t.Position, Children: elements}
	}
	panic(&SyntaxError{t})
}
func (p *Parser) pattern() *Expr {
	first := p.patternAtom()
	if _, ok := p.accept("::"); ok {
		return &Expr{Kind: "cons", Position: first.Position, Children: []*Expr{first, p.pattern()}}
	}
	return first
}
func (p *Parser) patternAtom() *Expr {
	t := p.peek()
	if t.Kind == "identifier" {
		p.Index++
		kind := "name"
		if t.Spelling == "_" {
			kind = "wildcard"
		}
		return &Expr{Kind: kind, Position: t.Position, Value: t.Spelling}
	}
	if _, ok := p.accept("-"); ok {
		number := p.expect("integer")
		return &Expr{Kind: "integer", Position: t.Position, Integer: -number.Integer}
	}
	if wordIn("integer string true false", t.Kind) {
		return p.atom()
	}
	if _, ok := p.accept("("); ok {
		first := p.pattern()
		if _, yes := p.accept(","); yes {
			second := p.pattern()
			p.expect(")")
			return &Expr{Kind: "pair", Position: t.Position, Children: []*Expr{first, second}}
		}
		p.expect(")")
		return first
	}
	if _, ok := p.accept("["); ok {
		elements := []*Expr{}
		if _, yes := p.accept("]"); !yes {
			elements = append(elements, p.pattern())
			for {
				if _, yes := p.accept(";"); !yes {
					break
				}
				elements = append(elements, p.pattern())
			}
			p.expect("]")
		}
		return &Expr{Kind: "list", Position: t.Position, Children: elements}
	}
	panic(&SyntaxError{t})
}
func (p *Parser) typeExpression() *Expr {
	first := p.listType()
	if _, ok := p.accept("*"); ok {
		first = &Expr{Kind: "pair", Position: first.Position, Children: []*Expr{first, p.listType()}}
	}
	if _, ok := p.accept("->"); ok {
		first = &Expr{Kind: "function", Position: first.Position, Children: []*Expr{first, p.typeExpression()}}
	}
	return first
}
func (p *Parser) listType() *Expr {
	e := p.typeAtom()
	for p.peek().Kind == "identifier" && p.peek().Spelling == "list" {
		p.Index++
		e = &Expr{Kind: "list", Position: e.Position, Children: []*Expr{e}}
	}
	return e
}
func (p *Parser) typeAtom() *Expr {
	t := p.peek()
	if t.Kind == "identifier" && wordIn("int bool string", t.Spelling) {
		p.Index++
		return &Expr{Kind: t.Spelling, Position: t.Position}
	}
	if _, ok := p.accept("type_variable"); ok {
		return &Expr{Kind: "type_variable", Position: t.Position, Value: t.Spelling}
	}
	if _, ok := p.accept("("); ok {
		e := p.typeExpression()
		p.expect(")")
		return e
	}
	panic(&SyntaxError{t})
}

package main

type Type struct {
	Kind     string
	Children []*Type
	Binding  *Type
}
type Scheme struct {
	Type       *Type
	Quantified map[*Type]bool
}
type TypeEnv map[string]Scheme

var intType = &Type{Kind: "int"}
var boolType = &Type{Kind: "bool"}
var stringType = &Type{Kind: "string"}

func fresh() *Type                                     { return &Type{Kind: "var"} }
func constructed(kind string, children ...*Type) *Type { return &Type{Kind: kind, Children: children} }
func resolve(t *Type) *Type {
	if t.Kind == "var" && t.Binding != nil {
		t.Binding = resolve(t.Binding)
		return t.Binding
	}
	return t
}
func occurs(variable, t *Type) bool {
	t = resolve(t)
	if t == variable {
		return true
	}
	for _, child := range t.Children {
		if occurs(variable, child) {
			return true
		}
	}
	return false
}

type UnificationFailure struct {
	Expected, Found  *Type
	Infinite, Nested bool
}

func unify(expected, found *Type, nested bool) *UnificationFailure {
	expected, found = resolve(expected), resolve(found)
	if expected == found {
		return nil
	}
	if expected.Kind == "var" {
		if occurs(expected, found) {
			return &UnificationFailure{expected, found, true, nested}
		}
		expected.Binding = found
		return nil
	}
	if found.Kind == "var" {
		if occurs(found, expected) {
			return &UnificationFailure{expected, found, true, nested}
		}
		found.Binding = expected
		return nil
	}
	if expected.Kind != found.Kind {
		return &UnificationFailure{expected, found, false, nested}
	}
	for i, child := range expected.Children {
		if failure := unify(child, found.Children[i], true); failure != nil {
			return failure
		}
	}
	return nil
}
func freeVariables(t *Type) map[*Type]bool {
	out := map[*Type]bool{}
	var walk func(*Type)
	walk = func(value *Type) {
		value = resolve(value)
		if value.Kind == "var" {
			out[value] = true
			return
		}
		for _, child := range value.Children {
			walk(child)
		}
	}
	walk(t)
	return out
}
func generalize(t *Type, env TypeEnv) Scheme {
	quantified := freeVariables(t)
	for _, scheme := range env {
		for variable := range freeVariables(scheme.Type) {
			if !scheme.Quantified[variable] {
				delete(quantified, variable)
			}
		}
	}
	return Scheme{t, quantified}
}
func instantiate(s Scheme) *Type {
	replacements := map[*Type]*Type{}
	var copy func(*Type) *Type
	copy = func(t *Type) *Type {
		t = resolve(t)
		if t.Kind == "var" {
			if !s.Quantified[t] {
				return t
			}
			if replacements[t] == nil {
				replacements[t] = fresh()
			}
			return replacements[t]
		}
		children := []*Type{}
		for _, child := range t.Children {
			children = append(children, copy(child))
		}
		return constructed(t.Kind, children...)
	}
	return copy(s.Type)
}
func copyTypes(env TypeEnv) TypeEnv {
	out := TypeEnv{}
	for name, scheme := range env {
		out[name] = scheme
	}
	return out
}
